{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Launch configuration EBS volume is not encrypted",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not explicitly encrypt its root EBS volume, which may leave data at rest unencrypted."
    },
    {
      "check_id": "CKV_AWS_389",
      "title": "Launch configuration assigns public IP addresses",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration explicitly enables public IP assignment, unnecessarily exposing launched instances to direct internet reachability."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "IMDSv2 tokens are not required",
      "resource": "aws_launch_configuration.lc",
      "severity": "HIGH",
      "explanation": "The launch configuration does not require session tokens for instance metadata access, allowing use of the less secure IMDSv1 protocol."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n\n  root_block_device {\n    encrypted = true\n  }\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n\n  user_data = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n}\n",
  "fix_summary": "Disabled public IP assignment, enabled encryption for the root EBS volume, and required IMDSv2 session tokens for instances created from the launch configuration."
}
